// Unisce le costellazioni alle schede: le sei già presenti ricevono stelle e visibilità,
// le altre diventano schede nuove (che non compaiono nell'elenco di "Stasera", per non allungarlo troppo).
for (const c of COSTELLAZIONI) {
  const esistente = OGGETTI.find((o) => o.id === c.id);
  if (esistente) {
    const { cosa, quando, dove, come, origine, storia, ra, dec, mag, immagine, ...nuovi } = c;
    Object.assign(esistente, nuovi);
  } else OGGETTI.push({ ...c, stasera: false });
}
